#!/usr/bin/env node

import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { buildDeck, CARD_BLUEPRINTS } from "./deck.mjs";
import { dueCards, RATINGS, scheduleReview, summarizeDeck } from "./scheduler.mjs";

const currentDirectory = path.dirname(fileURLToPath(import.meta.url));
const curriculumRoot = path.resolve(currentDirectory, "..");
const statePath = path.join(currentDirectory, ".state.json");

async function loadState() {
  try {
    const parsed = JSON.parse(await readFile(statePath, "utf8"));
    return {
      version: 1,
      reviews: parsed.reviews && typeof parsed.reviews === "object" ? parsed.reviews : {},
    };
  } catch (error) {
    if (error.code === "ENOENT") return { version: 1, reviews: {} };
    throw new Error(`Could not read ${statePath}: ${error.message}`);
  }
}

async function saveState(state) {
  await mkdir(currentDirectory, { recursive: true });
  await writeFile(statePath, `${JSON.stringify(state, null, 2)}\n`, "utf8");
}

function printCard(card, includeCriteria = true) {
  console.log(`\n[${card.typeName}] ${card.source}`);
  console.log(`ID: ${card.id}`);
  console.log(`\n${card.question}`);
  if (includeCriteria) {
    console.log("\nA strong response includes:");
    card.criteria.forEach(item => console.log(`- ${item}`));
  }
}

function positiveInteger(value, fallback) {
  const parsed = Number.parseInt(value, 10);
  return Number.isInteger(parsed) && parsed > 0 ? parsed : fallback;
}

function findCard(cards, query) {
  const exact = cards.find(card => card.id === query);
  if (exact) return exact;

  const matches = cards.filter(
    card => card.id.includes(query) || card.source.toLowerCase().includes(query.toLowerCase()),
  );
  if (matches.length === 1) return matches[0];
  if (matches.length === 0) throw new Error(`No card matches “${query}”.`);
  throw new Error(`Query matches ${matches.length} cards; use the full card ID.`);
}

function printUsage() {
  console.log(`Spaced repetition commands:

  npm run study -- stats
  npm run study -- due [count]
  npm run study -- source <path-fragment>
  npm run study -- show <card-id>
  npm run study -- answer <card-id>
  npm run study -- review <card-id> <again|hard|good|easy>
  npm run study -- coverage
  npm run study -- types

Answer before reading the criteria. Use "again" when the answer was absent or
incorrect, "hard" when substantial prompting was needed, "good" for independent
recall and application, and "easy" only when transfer was also successful.`);
}

async function main() {
  const [command = "help", ...args] = process.argv.slice(2);
  const cards = await buildDeck(curriculumRoot);
  const state = await loadState();

  if (command === "help" || command === "--help" || command === "-h") {
    printUsage();
    return;
  }

  if (command === "stats") {
    const summary = summarizeDeck(cards, state.reviews);
    Object.entries(summary).forEach(([key, value]) => console.log(`${key}: ${value}`));
    return;
  }

  if (command === "coverage") {
    const sources = new Set(cards.map(card => card.source));
    console.log(`source files: ${sources.size}`);
    console.log(`card types per file: ${CARD_BLUEPRINTS.length}`);
    console.log(`total cards: ${cards.length}`);
    console.log(`coverage complete: ${cards.length === sources.size * CARD_BLUEPRINTS.length}`);
    return;
  }

  if (command === "types") {
    CARD_BLUEPRINTS.forEach((type, index) => console.log(`${index + 1}. ${type.name} (${type.id})`));
    return;
  }

  if (command === "due") {
    const count = positiveInteger(args[0], 5);
    const due = dueCards(cards, state.reviews).slice(0, count);
    if (due.length === 0) {
      console.log("No cards are due. Build something, rest, or attempt a transfer variant.");
      return;
    }
    due.forEach(card => printCard(card, false));
    return;
  }

  if (command === "source") {
    const query = args.join(" ").trim();
    if (!query) throw new Error("Provide a source path fragment.");
    const matches = cards.filter(card =>
      card.source.toLowerCase().includes(query.toLowerCase()),
    );
    if (matches.length === 0) throw new Error(`No source matches “${query}”.`);
    matches.forEach(card => printCard(card, false));
    return;
  }

  if (command === "show") {
    if (!args[0]) throw new Error("Provide a card ID.");
    printCard(findCard(cards, args[0]), false);
    return;
  }

  if (command === "answer") {
    if (!args[0]) throw new Error("Provide a card ID.");
    printCard(findCard(cards, args[0]), true);
    return;
  }

  if (command === "review") {
    const [cardQuery, rating] = args;
    if (!cardQuery || !rating) throw new Error("Provide a card ID and rating.");
    if (!RATINGS.includes(rating)) {
      throw new Error(`Rating must be one of: ${RATINGS.join(", ")}`);
    }
    const card = findCard(cards, cardQuery);
    const record = scheduleReview(state.reviews[card.id], rating);
    state.reviews[card.id] = record;
    await saveState(state);
    console.log(`Reviewed: ${card.source} / ${card.typeName}`);
    console.log(`Next due: ${record.due}`);
    console.log(`Stage: ${record.stage}; reviews: ${record.reviews}; lapses: ${record.lapses}`);
    return;
  }

  throw new Error(`Unknown command “${command}”. Run "npm run study -- help".`);
}

main().catch(error => {
  console.error(error.message);
  process.exitCode = 1;
});
